use std::collections::BTreeMap;
use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicU64, Ordering};

pub const HEADER: &str = "\
# SPDX-License-Identifier: GPL-3.0-or-later
# Copyright (C) 2026 VitruvianSoftware

# GENERATED by bazel/sync_sources.py from build.sh and Tests/generate_sources.py.
# Do not edit by hand: run `bazel run //apps/desktop/vitruvian:sync_sources`.
";

pub const NOW_PLAYING_ENTRY: &str = "Sources/NowPlayingAdapter/NowPlayingAdapter.swift";
pub const NOW_PLAYING_STAGING: &[(&str, &str)] = &[
    (
        "Contents/Frameworks/$NOW_PLAYING_ADAPTER",
        "build/$NOW_PLAYING_ADAPTER",
    ),
    (
        "Contents/Resources/now-playing.pl",
        "Resources/now-playing.pl",
    ),
];

pub const CORE_IMPORT: &str =
    "import VitruvianCore\nimport VitruvianDesign\nimport VitruvianServices\nimport VitruvianUI\n";

pub struct Config {
    pub check: bool,
    pub app_dir: Option<PathBuf>,
    pub emit_generated: Option<PathBuf>,
}

pub fn parse_args(args: &[String]) -> Result<Config, String> {
    let mut check = false;
    let mut app_dir = None;
    let mut emit_generated = None;
    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "--check" => check = true,
            "--app-dir" => {
                i += 1;
                if i >= args.len() {
                    return Err("--app-dir requires a value".into());
                }
                app_dir = Some(PathBuf::from(&args[i]));
            }
            "--emit-generated" => {
                i += 1;
                if i >= args.len() {
                    return Err("--emit-generated requires a value".into());
                }
                emit_generated = Some(PathBuf::from(&args[i]));
            }
            "-h" | "--help" => {
                return Err(
                    "Usage: sync_sources [--check] [--app-dir <path>] [--emit-generated <dir>]"
                        .into(),
                );
            }
            other => return Err(format!("unknown argument: {}", other)),
        }
        i += 1;
    }
    Ok(Config {
        check,
        app_dir,
        emit_generated,
    })
}

fn block<'a>(text: &'a str, start_marker: &str, end_marker: &str) -> Result<&'a str, String> {
    let start = text
        .find(start_marker)
        .ok_or_else(|| format!("start marker not found: {:?}", start_marker))?;
    let rel_end = text[start..]
        .find(end_marker)
        .ok_or_else(|| format!("end marker not found: {:?}", end_marker))?;
    Ok(&text[start..start + rel_end])
}

fn is_swift_path_char(b: u8) -> bool {
    b.is_ascii_alphanumeric() || matches!(b, b'_' | b'.' | b'/' | b'+' | b'*' | b'-')
}

pub fn swift_paths(block_str: &str) -> Vec<String> {
    let mut out = Vec::new();
    let bytes = block_str.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        while i < bytes.len() && !is_swift_path_char(bytes[i]) {
            i += 1;
        }
        let start = i;
        while i < bytes.len() && is_swift_path_char(bytes[i]) {
            i += 1;
        }
        if start < i {
            let token = &block_str[start..i];
            if let Some(pos) = token.find(".swift") {
                out.push(token[..pos + ".swift".len()].to_string());
            }
        }
    }
    out
}

pub fn test_sources(build_sh: &str) -> Result<Vec<String>, String> {
    let blk = block(build_sh, "    TEST_SOURCES=(\n", "\n    )\n")?;
    let mut out = Vec::new();
    for line in blk.lines().skip(1) {
        let p = line.trim();
        if p.starts_with("Sources/") {
            out.push(p.to_string());
        }
    }
    Ok(out)
}

pub fn fan_helper_sources(build_sh: &str) -> Result<Vec<String>, String> {
    let blk = block(
        build_sh,
        "echo \"▸ Compiling protected fan helper…\"",
        "-o \"build/$FAN_HELPER_ID\"",
    )?;
    Ok(swift_paths(blk))
}

pub fn now_playing_sources(build_sh: &str) -> Result<Vec<String>, String> {
    let blk = block(
        build_sh,
        "echo \"▸ Compiling Now Playing adapter…\"",
        "-o \"build/$NOW_PLAYING_ADAPTER\"",
    )?;
    Ok(swift_paths(blk))
}

pub fn staged_files(build_sh: &str) -> BTreeMap<String, String> {
    let mut map = BTreeMap::new();
    for line in build_sh.lines() {
        let Some(rest) = line.strip_prefix("cp ") else {
            continue;
        };
        let Some((src_part, dst_part)) = rest.split_once(" \"$STAGE/") else {
            continue;
        };
        let Some(dest) = dst_part.strip_suffix('"') else {
            continue;
        };
        if !dest.starts_with("Contents/") || dest.contains('"') {
            continue;
        }
        let source = src_part.trim_matches('"');
        if source.is_empty() || source.chars().any(|c| c.is_whitespace() || c == '"') {
            continue;
        }
        map.insert(dest.to_string(), source.to_string());
    }
    map
}

pub fn now_playing_problems(build_sh: &str) -> Result<Vec<String>, String> {
    let mut problems = Vec::new();
    let np_sources = now_playing_sources(build_sh)?;
    if !np_sources.iter().any(|s| s == NOW_PLAYING_ENTRY) {
        problems.push(format!(
            "build.sh no longer compiles {} into the adapter",
            NOW_PLAYING_ENTRY
        ));
    }
    let staged = staged_files(build_sh);
    for (dest, source) in NOW_PLAYING_STAGING {
        if staged.get(*dest).map(|s| s.as_str()) != Some(*source) {
            problems.push(format!("build.sh no longer stages {} as {}", source, dest));
        }
    }
    Ok(problems)
}

static SCRATCH_COUNTER: AtomicU64 = AtomicU64::new(0);

fn make_scratch_dir() -> PathBuf {
    let base = env::var("TEST_TMPDIR")
        .map(PathBuf::from)
        .unwrap_or_else(|_| env::temp_dir());
    let id = SCRATCH_COUNTER.fetch_add(1, Ordering::Relaxed);
    let dir = base.join(format!(
        "sync_sources_scratch_{}_{}",
        std::process::id(),
        id
    ));
    let _ = fs::remove_dir_all(&dir);
    fs::create_dir_all(&dir).expect("create scratch dir");
    dir
}

pub fn run_test_generator(app_dir: &Path, out_dir: &Path) -> Result<Vec<String>, String> {
    let scratch = make_scratch_dir();
    let names = generate_sources::generate(app_dir, &scratch);
    let names = match names {
        Ok(n) => n,
        Err(e) => {
            let _ = fs::remove_dir_all(&scratch);
            return Err(e);
        }
    };
    fs::create_dir_all(out_dir)
        .map_err(|e| format!("failed to create {}: {}", out_dir.display(), e))?;
    for name in &names {
        let text = fs::read_to_string(scratch.join(name))
            .map_err(|e| format!("failed to read generated {}: {}", name, e))?;
        let mut with_import = String::with_capacity(CORE_IMPORT.len() + text.len());
        with_import.push_str(CORE_IMPORT);
        with_import.push_str(&text);
        fs::write(out_dir.join(name), with_import)
            .map_err(|e| format!("failed to write {}: {}", out_dir.join(name).display(), e))?;
    }
    let _ = fs::remove_dir_all(&scratch);
    Ok(names)
}

pub fn generated_test_sources(app_dir: &Path) -> Result<Vec<String>, String> {
    let out = make_scratch_dir();
    let res = run_test_generator(app_dir, &out);
    let _ = fs::remove_dir_all(&out);
    res
}

fn format_list(name: &str, items: &[String]) -> String {
    let mut out = format!("{} = [\n", name);
    for item in items {
        out.push_str(&format!("    \"{}\",\n", item));
    }
    out.push_str("]\n");
    out
}

pub fn render(app_dir: &Path) -> Result<String, String> {
    let build_sh_path = app_dir.join("build.sh");
    let build_sh = fs::read_to_string(&build_sh_path)
        .map_err(|e| format!("failed to read {}: {}", build_sh_path.display(), e))?;
    let test_srcs = test_sources(&build_sh)?;
    let gen_srcs = generated_test_sources(app_dir)?;
    let fan_srcs = fan_helper_sources(&build_sh)?;
    let np_srcs = now_playing_sources(&build_sh)?;

    Ok([
        HEADER.to_string(),
        "# Production sources build.sh compiles into the unit-test binary, in its order."
            .to_string(),
        format_list("TEST_PRODUCTION_SOURCES", &test_srcs),
        "# Files Tests/generate_sources.py writes; Bazel needs them declared up front.".to_string(),
        format_list("GENERATED_TEST_SOURCES", &gen_srcs),
        "# Sources of the privileged fan-control helper.".to_string(),
        format_list("FAN_HELPER_SOURCES", &fan_srcs),
        "# Sources of the Now Playing adapter dylib loaded through /usr/bin/perl.".to_string(),
        format_list("NOW_PLAYING_SOURCES", &np_srcs),
    ]
    .join("\n"))
}

pub fn resolve_app_dir(arg: Option<PathBuf>) -> PathBuf {
    let dir = arg.unwrap_or_else(|| {
        if let Ok(ws) = env::var("BUILD_WORKSPACE_DIRECTORY") {
            PathBuf::from(ws).join("apps/desktop/vitruvian")
        } else if Path::new("apps/desktop/vitruvian/build.sh").is_file() {
            PathBuf::from("apps/desktop/vitruvian")
        } else {
            env::current_dir().unwrap_or_else(|_| PathBuf::from("."))
        }
    });
    if dir.is_absolute() {
        dir
    } else {
        env::current_dir()
            .unwrap_or_else(|_| PathBuf::from("."))
            .join(dir)
    }
}

pub fn run_cli(args: &[String]) -> i32 {
    let config = match parse_args(args) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("{}", e);
            return 2;
        }
    };
    let app_dir = resolve_app_dir(config.app_dir);

    if let Some(emit_dir) = config.emit_generated {
        let abs_emit = if emit_dir.is_absolute() {
            emit_dir
        } else {
            env::current_dir()
                .unwrap_or_else(|_| PathBuf::from("."))
                .join(emit_dir)
        };
        if let Err(e) = run_test_generator(&app_dir, &abs_emit) {
            eprintln!("{}", e);
            return 1;
        }
        return 0;
    }

    let expected = match render(&app_dir) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("{}", e);
            return 1;
        }
    };
    let target = app_dir.join("bazel/sources.bzl");
    if config.check {
        let build_sh = match fs::read_to_string(app_dir.join("build.sh")) {
            Ok(s) => s,
            Err(e) => {
                eprintln!("{}", e);
                return 1;
            }
        };
        let problems = match now_playing_problems(&build_sh) {
            Ok(p) => p,
            Err(e) => {
                eprintln!("{}", e);
                return 1;
            }
        };
        for problem in &problems {
            eprintln!("{}", problem);
        }
        if !problems.is_empty() {
            return 1;
        }
        let current = fs::read_to_string(&target).unwrap_or_default();
        if current != expected {
            eprintln!(
                "{} is stale. Run: bazel run //apps/desktop/vitruvian:sync_sources",
                target.display()
            );
            return 1;
        }
        println!("bazel/sources.bzl matches build.sh and Tests/generate_sources.py");
        return 0;
    }

    if let Err(e) = fs::write(&target, expected) {
        eprintln!("failed to write {}: {}", target.display(), e);
        return 1;
    }
    println!("wrote {}", target.display());
    0
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_sources_in_sync() {
        let app_dir = resolve_app_dir(Some(PathBuf::from("apps/desktop/vitruvian")));
        assert_eq!(
            run_cli(&[
                "--check".to_string(),
                "--app-dir".to_string(),
                app_dir.to_string_lossy().to_string(),
            ]),
            0
        );
    }
}
